$ErrorActionPreference = "Stop"\n$Repo = "$env:USERPROFILE\Downloads\Outcom"\n$Source = Split-Path -Parent $MyInvocation.MyCommand.Path\nif (!(Test-Path $Repo)) { throw "Repo tidak ditemukan: $Repo" }\nSet-Location $Repo\nWrite-Host "[1/5] Copying V75.1..." -ForegroundColor Yellow\nrobocopy $Source $Repo /E /NFL /NDL /NJH /NJS /NP\nif ($LASTEXITCODE -gt 7) { throw "Robocopy gagal dengan exit code $LASTEXITCODE" }\nWrite-Host "[2/5] Running V75.1 checks..." -ForegroundColor Yellow\nnode scripts\v751-check.mjs\nif ($LASTEXITCODE -ne 0) { throw "V75.1 structural check FAILED. Push dibatalkan." }\nWrite-Host "[3/5] git diff --check..." -ForegroundColor Yellow\ngit diff --check\nif ($LASTEXITCODE -ne 0) { throw "git diff --check FAILED." }\nWrite-Host "[4/5] Commit..." -ForegroundColor Yellow\ngit add -A\ngit diff --cached --check\nif ($LASTEXITCODE -ne 0) { throw "Staged diff check FAILED." }\ngit commit -m "V75.1: polish protected outcomes and reliability UX"\nif ($LASTEXITCODE -ne 0) { throw "Git commit gagal." }\nWrite-Host "[5/5] Push main..." -ForegroundColor Yellow\ngit push origin main\nif ($LASTEXITCODE -ne 0) { throw "Git push gagal." }\nWrite-Host "V75.1 PUSH BERHASIL" -ForegroundColor Green\nRead-Host "Tekan ENTER untuk menutup"\n